<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Leaderboard — Solomon</title><link rel="stylesheet" href="assets/css/main.css"></head><body><main class="panel wide"><h1>GLOBAL LEADERBOARD</h1><table><thead><tr><th>Rank</th><th>Player</th><th>Level</th><th>Score</th><th>Time</th></tr></thead><tbody id="rows"></tbody></table><a href="index.php">Home</a></main><script>fetch('api/leaderboard.php').then(r=>r.json()).then(d=>rows.innerHTML=d.leaderboard.map((x,i)=>`<tr><td>${i+1}</td><td>${x.username}</td><td>${x.name}</td><td>${x.score}</td><td>${Number(x.completion_time).toFixed(2)}s</td></tr>`).join(''));</script></body></html>
